// 策略进化 page acceptance: PANEL_URL=http://127.0.0.1:8008/ node tests/evolve_browser.cjs
// Serves tests/fixtures/evolve-dashboard.json (generated by tools/evolve/run.py) through route interception.
const { chromium, devices } = require('playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const BASE = process.env.PANEL_URL || 'http://127.0.0.1:8008/';
const dash = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'evolve-dashboard.json'), 'utf8'));
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ ...devices['iPhone 13'] });
  let mode = 'ok';
  await context.addInitScript(() => { try { localStorage.setItem('modi-companion-position', JSON.stringify({ side: 'right', bottom: 20, docked: true })); } catch {} });
  await context.route(/okx\.com/, r => r.abort()); await context.routeWebSocket(/okx\.com/, ws => ws.close());
  await context.route('**/paper-data/evolve/dashboard.json*', r => mode === 'ok' ? r.fulfill({ contentType: 'application/json', body: JSON.stringify(dash) }) : r.fulfill({ status: 404, body: '404' }));
  const page = await context.newPage(), errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto(BASE + '#/evolve');
  await page.waitForSelector('#evolve-graph svg');
  // The gene pool replays its history on first view, generation by generation, then rests on the current state.
  await page.waitForSelector('#evolve-graph svg.replay', { timeout: 10000 });
  assert.equal(await page.locator('#evolve-play, #evolve-scrub').count(), 0);           // no replay controls: it just plays
  assert.match(await page.locator('#evolve-graph .evo-gen-label').textContent(), /第 \d+ 代/);
  await page.waitForFunction(() => !document.querySelector('#evolve-graph svg.replay'), null, { timeout: 20000 });
  assert.equal(await page.locator('#evolve-graph .future').count(), 0);
  // After the replay the canvas overlay animates: halos and sparks are drawn (non-empty pixels that change over time).
  const ink = () => page.evaluate(() => { const c = document.querySelector('#evolve-graph canvas.evo-fx'), d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let n = 0, h = 0; for (let i = 3; i < d.length; i += 4) if (d[i]) { n++; h = (h * 31 + i + d[i]) % 1e9; } return [n, h]; });
  await page.locator('#evolve-graph').scrollIntoViewIfNeeded(); await page.waitForTimeout(300); const f1 = await ink(); await page.waitForTimeout(700); const f2 = await ink();
  assert.ok(f1[0] > 0 && f2[0] > 0); assert.notEqual(f1[1], f2[1]);
  // Reload and click a node mid-replay: the replay stops and the full pool is shown with that node selected.
  await page.reload(); await page.waitForSelector('#evolve-graph svg.replay', { timeout: 10000 });
  await page.locator(`#evolve-graph [data-node="${dash.champion.id}"]`).dispatchEvent('click');
  await page.waitForFunction(() => !document.querySelector('#evolve-graph svg.replay'));
  assert.equal(await page.locator('[data-nav="evolve"]').getAttribute('aria-current'), 'page');
  assert.match(await page.title(), /策略进化/);
  assert.match(await page.locator('#evolve-loop').innerText(), new RegExp(`${dash.generation}[\\s\\S]*观察波动|观察波动[\\s\\S]*${dash.generation}`));
  assert.equal(await page.locator('#evolve-graph .evo-node').count(), dash.nodes.length);
  assert.equal(await page.locator('#evolve-fitness polyline').count(), 2);
  // The champion is selected first; clicking any node shows its genes and backtest.
  assert.match(await page.locator('#evolve-detail').innerText(), new RegExp(`${dash.champion.id}[\\s\\S]*冠军组合领头 · 纸面交易中`));
  const child = dash.nodes.find(n => n.parents.length === 2 && n.parents.every(p => dash.nodes.some(x => x.id === p)));
  await page.locator(`#evolve-graph [data-node="${child.id}"]`).dispatchEvent('click');
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), child.id);
  const detail = await page.locator('#evolve-detail').innerText();
  assert.match(detail, /训练集 60%/); assert.match(detail, /样本外 20%/); assert.match(detail, /终审 20%/); assert.match(detail, /基因/);
  assert.ok(await page.locator(`#evolve-graph [data-node="${child.id}"].sel`).count() === 1);
  assert.ok(await page.locator('#evolve-graph .evo-edge.hot').count() >= 2);                     // lineage highlighted
  // Parent buttons in the detail navigate the lineage.
  await page.locator(`#evolve-detail [data-node="${child.parents[0]}"]`).click();
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), child.parents[0]);
  // Keyboard: focus a node and press Enter.
  const other = dash.nodes.find(n => n.id !== child.parents[0] && n.id !== dash.champion.id);
  await page.locator(`#evolve-graph [data-node="${other.id}"]`).focus(); await page.keyboard.press('Enter');
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), other.id);
  assert.match(await page.locator('#evolve-paper').innerText(), /纸面权益[\s\S]*冠军组合/);
  assert.equal(await page.locator('#evolve-paper li.evo-member').count(), dash.team.length);
  assert.equal(await page.locator('#evolve-graph .team-ring, #evolve-graph .champ-ring').count(), dash.team.length);   // every member ringed
  await page.locator(`#evolve-paper li.evo-member[data-node="${dash.team[2].id}"]`).click();                          // member row opens its detail
  await page.waitForFunction(id => document.querySelector('#evolve-detail h3').textContent.includes(id), dash.team[2].id);
  assert.match(await page.locator('#evolve-caption').innerText(), /训练集[\s\S]*样本外/);
  for (const width of [320, 390]) {
    await page.setViewportSize({ width, height: 844 });
    assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), `page overflow at ${width}`);
  }
  // Home shows a compact evolution card that links here.
  await page.goto(BASE + '#/'); await page.waitForSelector('#home-evolve:not([hidden])', { timeout: 20000 }).catch(() => {});
  if (await page.locator('#home-sim').isVisible()) assert.match(await page.locator('#home-evolve').innerText(), new RegExp(`第 ${dash.generation} 代`));
  // Slim lineage nodes: the page loads and nodes.json only when a node without details is opened (once).
  { const seated = new Set([...(dash.team || []).map(m => m.id), dash.champion.id]);
    // What the engine writes now: schema 1 (older pages keep working) with genes on every node, summaries / curves in nodes.json.
    const slim = { ...dash, details: 'nodes.json', nodes: dash.nodes.map(n => seated.has(n.id) ? n : Object.fromEntries(Object.entries(n).filter(([k]) => !['summary', 'test_curve', 'train_curve'].includes(k)))) };
    const det = { schema: 1, generation: dash.generation, nodes: Object.fromEntries(dash.nodes.map(n => [n.id, { genes: n.genes, summary: n.summary, test_curve: n.test_curve }])) };
    const ctx = await browser.newContext({ ...devices['iPhone 13'], reducedMotion: 'reduce' }); let detailHits = 0;
    await ctx.route(/okx\.com/, r => r.abort());
    await ctx.route('**/paper-data/evolve/dashboard.json*', r => r.fulfill({ contentType: 'application/json', body: JSON.stringify(slim) }));
    await ctx.route('**/paper-data/evolve/nodes.json*', async r => { detailHits++; await new Promise(x => setTimeout(x, 400)); r.fulfill({ contentType: 'application/json', body: JSON.stringify(det) }); });
    const sp = await ctx.newPage(); const errs = []; sp.on('pageerror', e => errs.push(String(e)));
    await sp.goto(BASE + '#/'); await sp.waitForSelector('#home-evolve:not([hidden])'); await sp.waitForTimeout(500);
    assert.equal(detailHits, 0);                                                     // home card never needs the details
    await sp.goto(BASE + '#/evolve'); await sp.waitForSelector('#evolve-graph svg');
    assert.match(await sp.locator('#evolve-detail').innerText(), /基因/); assert.equal(detailHits, 0);   // champion: already complete
    const other = slim.nodes.find(n => !seated.has(n.id));
    await sp.locator(`#evolve-graph [data-node="${other.id}"]`).dispatchEvent('click');
    await sp.waitForSelector('#evolve-detail .evo-loading');
    await sp.waitForSelector('#evolve-detail .evo-genes');
    const another = slim.nodes.filter(n => !seated.has(n.id))[1];
    await sp.locator(`#evolve-graph [data-node="${another.id}"]`).dispatchEvent('click'); await sp.waitForSelector('#evolve-detail .evo-genes');
    assert.equal(detailHits, 1); assert.deepEqual(errs, []); await ctx.close(); }
  // Reduced motion: no automatic replay.
  { const still = await browser.newContext({ ...devices['iPhone 13'], reducedMotion: 'reduce' });
    await still.route(/okx\.com/, r => r.abort()); await still.route('**/paper-data/evolve/dashboard.json*', r => r.fulfill({ contentType: 'application/json', body: JSON.stringify(dash) }));
    const sp = await still.newPage(); await sp.goto(BASE + '#/evolve'); await sp.waitForSelector('#evolve-graph svg'); await sp.waitForTimeout(800);
    assert.equal(await sp.locator('#evolve-graph svg.replay').count(), 0); await still.close(); }
  // Before the first run the page explains what will appear.
  mode = 'missing'; const fresh = await context.newPage(); await fresh.goto(BASE + '#/evolve');
  await fresh.waitForSelector('#evolve-error:not([hidden])');
  assert.match(await fresh.locator('#evolve-error').innerText(), /还没有运行过/);
  assert.deepEqual(errors, []);
  await browser.close();
  console.log('策略进化页验收通过：进化循环与代数、适应度曲线、基因池节点与谱系、点击 / 键盘查看基因与训练 vs 样本外回测、父代跳转、纸面交易、首页卡片、320/390 无溢出、首次运行前提示、pageerror=0。');
})().catch(e => { console.error(e); process.exit(1); });
